function demoMain(idx,label){
  var texts=["aaaaaaaaaabbbbbbbbbbcccccccccc","hello hello hello hello world","xyz xyz xyz xyz xyz xyz xyz"];
  var t=texts[idx%texts.length];
  var runs=1;for(var i=1;i<t.length;i++){if(t[i]!==t[i-1])runs++;}
  var ratio=(t.length/runs).toFixed(1);
  return "["+label+"] RLE compressed "+t.length+" chars -> "+runs+" runs (ratio "+ratio+":1)";
}

